import numpy as np
def test(actions, n=256):
    obs, _ = observe(params=W, actions=actions, n_steps=n)
    T = obs.shape[0]
    gx, gy = obs[:,234], obs[:,235]
    bx, by = obs[:,26], obs[:,27]
    d = np.hypot(gx-bx, gy-by)
    rx, ry = obs[:,104], obs[:,105]
    dr = np.hypot(gx-rx, gy-ry)
    return T, float(d.min()), float(dr.min()), (float(gx[-1]), float(gy[-1]))

pats = {}
# Longer off periods to let wheel settle
for on in [2,3,4,5]:
    for off in [5,8,12,16,20]:
        pats[f'on{on}_off{off}'] = ([1]*on + [0]*off)*30

results = []
for name, acts in pats.items():
    T, dmin, drmin, gend = test(acts)
    results.append((T, dmin, name, gend, drmin))

results.sort(key=lambda x: (-x[0], x[1]))
for T, dmin, name, gend, drmin in results[:15]:
    print(f"{name:15s} T={T:3d} dmin_blue={dmin:.3f} dmin_red={drmin:.3f} gend=({gend[0]:.2f},{gend[1]:.2f})")
